eq(v,1.3295116111392817e-39)
eq(r:raw_hex(),"0a7d3da94ecde8b8")
end
do local r=np.random.default_rng(0);local v=r:noncentral_chisquare(0.01,0.0,{})
eq(v.dtype,"float64")
eq(#v.shape,0)
eq(v:get(),1.3295116111392817e-39)
